document.querySelectorAll('.video-shell').forEach(shell=>{const launch=shell.querySelector('button'),video=shell.querySelector('video'),status=shell.querySelector('.video-status');launch.addEventListener('click',()=>{video.src=video.dataset.src;video.hidden=false;launch.hidden=true;video.focus();video.play().catch(()=>{status.hidden=false;status.textContent='請使用影片上的播放按鈕開始觀看。';});});video.addEventListener('play',()=>{status.hidden=true;document.querySelectorAll('video').forEach(other=>{if(other!==video)other.pause();});});video.addEventListener('error',()=>{status.hidden=false;status.textContent='影片暫時無法載入，請點擊封面重試。';video.hidden=true;launch.hidden=false;});});
